#include "spincore/neural_encoder.hpp"
#include <bit>
#include <cstring>
#include <stdexcept>
namespace spincore {
NeuralInputV1 encode_neural_input_v1(const CanonicalInfoset&i){NeuralInputV1 o{};o.card_tokens[0]=(std::uint8_t)(i.hole[0].id()+1);o.card_tokens[1]=(std::uint8_t)(i.hole[1].id()+1);for(int j=0;j<i.visible_board;++j)o.card_tokens[(std::size_t)(j+2)]=(std::uint8_t)(i.board[(std::size_t)j].id()+1);float bb=(float)i.big_blind;o.numeric[0]=i.pot/bb;o.numeric[1]=i.to_call/bb;o.numeric[2]=i.current_bet/bb;for(int j=0;j<3;++j){o.numeric[3+j]=i.stacks[(std::size_t)j]/bb;o.numeric[6+j]=i.street_commitments[(std::size_t)j]/bb;o.numeric[9+j]=i.total_commitments[(std::size_t)j]/bb;}o.numeric[12]=i.small_blind/bb;o.numeric[13]=1.0f;o.numeric[14]=(float)i.blind_index;o.numeric[15]=(float)i.live_count;o.categorical[0]=(std::uint8_t)i.domain;o.categorical[1]=(std::uint8_t)i.street;o.categorical[2]=i.dealer_rel;o.categorical[3]=i.live_count;for(int j=0;j<3;++j)o.categorical[4+j]=i.statuses[(std::size_t)j];o.categorical[7]=i.visible_board;o.legal_action_mask=i.legal_action_mask;o.history_len=(std::uint8_t)std::min<std::size_t>(32,i.public_history.size());for(std::size_t j=0;j<o.history_len;++j)o.history_tokens[j]=i.public_history[i.public_history.size()-o.history_len+j];return o;}
std::vector<std::uint8_t> serialize_neural_input_v1(const NeuralInputV1&i){std::vector<std::uint8_t>b;const char magic[8]={'S','P','N','N','I','V','1','\0'};b.insert(b.end(),magic,magic+8);b.insert(b.end(),i.card_tokens.begin(),i.card_tokens.end());for(float x:i.numeric){std::uint32_t u=std::bit_cast<std::uint32_t>(x);for(int k=0;k<4;++k)b.push_back((std::uint8_t)((u>>(8*k))&0xff));}b.insert(b.end(),i.categorical.begin(),i.categorical.end());b.insert(b.end(),i.legal_action_mask.begin(),i.legal_action_mask.end());b.push_back(i.history_len);b.insert(b.end(),i.history_tokens.begin(),i.history_tokens.end());return b;}
}
